import{_ as t,o as s,c as n,ag as e}from"./chunks/framework.KxDd3USm.js";const g=JSON.parse('{"title":"07.4 文法、推导与语法树 ★★","description":"","frontmatter":{},"headers":[],"relativePath":"07-程序设计语言基础/04-文法与推导.md","filePath":"07-程序设计语言基础/04-文法与推导.md"}'),o={name:"07-程序设计语言基础/04-文法与推导.md"};function p(d,a,r,i,l,c){return s(),n("div",null,[...a[0]||(a[0]=[e(`<h1 id="_07-4-文法、推导与语法树-★★" tabindex="-1">07.4 文法、推导与语法树 ★★ <a class="header-anchor" href="#_07-4-文法、推导与语法树-★★" aria-label="Permalink to &quot;07.4 文法、推导与语法树 ★★&quot;">​</a></h1><p><strong>动机</strong>：语法分析&quot;按语法规则组句&quot;，这条规则的形式化描述就是<strong>文法</strong>。</p><p>一个形式文法是四元组 <strong>G = (V, T, S, P)</strong>：</p><table tabindex="0"><thead><tr><th>成分</th><th>名称</th><th>含义</th></tr></thead><tbody><tr><td>V</td><td><strong>非终结符</strong></td><td>不是语言的最终组成部分，是&quot;占位符&quot;（如 <code>&lt;句子&gt;</code>、S、A）</td></tr><tr><td>T</td><td><strong>终结符</strong></td><td>语言的最终组成部分（如 a、b、关键字）</td></tr><tr><td>S</td><td><strong>起始符</strong></td><td>推导从它开始（S ∈ V）</td></tr><tr><td>P</td><td><strong>产生式</strong></td><td>替换规则，形如 A → α（用右部替换左部）</td></tr></tbody></table><p>例：文法 S → aSb | ε。从 S 出发反复推导：S ⇒ aSb ⇒ aaSbb ⇒ aabb。它描述的语言是 {aⁿbⁿ | n≥0}——非终结符 S 像&quot;待填的坑&quot;，终结符 a、b 才是最终结果。</p><h3 id="_5-1-推导、句型与句子" tabindex="-1">5.1 推导、句型与句子 <a class="header-anchor" href="#_5-1-推导、句型与句子" aria-label="Permalink to &quot;5.1 推导、句型与句子&quot;">​</a></h3><ul><li><code>α ⇒ β</code>：使用一次产生式，把 α 中某个非终结符替换后得到 β，称为<strong>直接推导</strong>；</li><li><code>α ⇒* β</code>：经过零次或多次推导得到；</li><li><strong>句型</strong>：从起始符 S 能推导出的符号串，可以同时含终结符和非终结符；</li><li><strong>句子</strong>：不再含非终结符的句型，即全部由终结符组成；</li><li><strong>语言 L(G)</strong>：文法 G 能生成的全部句子的集合。</li></ul><p><strong>反例演示（易错）</strong>：在文法 <code>S→aSb|ε</code> 中，<code>aaSbb</code> 是句型，但不是句子，因为 S 这个“待填坑”还没消失；<code>aabb</code> 才是句子。判断时不要看它“像不像单词”，只看是否还含非终结符。</p><h3 id="_5-2-最左推导与最右推导-只改变替换顺序" tabindex="-1">5.2 最左推导与最右推导：只改变替换顺序 <a class="header-anchor" href="#_5-2-最左推导与最右推导-只改变替换顺序" aria-label="Permalink to &quot;5.2 最左推导与最右推导：只改变替换顺序&quot;">​</a></h3><p>设文法：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>S → AB</span></span>
<span class="line"><span>A → aA | a</span></span>
<span class="line"><span>B → bB | b</span></span></code></pre></div><p>目标串 <code>aabb</code> 的<strong>最左推导</strong>（每一步只替换最左边的非终结符）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>S ⇒ AB ⇒ aAB ⇒ aaB ⇒ aabB ⇒ aabb</span></span></code></pre></div><p>目标串的<strong>最右推导</strong>（每一步只替换最右边的非终结符）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>S ⇒ AB ⇒ AbB ⇒ Abb ⇒ aAbb ⇒ aabb</span></span></code></pre></div><p>两条推导的中间句型不同，但终点都是 <code>aabb</code>。反向核对：A 只能生成一个或多个 a，B 只能生成一个或多个 b，因此任何句子都应是“若干 a 后接若干 b”；<code>aabb</code> 符合，而 <code>abab</code> 不可能由该文法生成。</p><p><strong>判串三步法</strong>：① 从 S 开始；② 每一步明确写出使用哪条产生式，不允许凭空换字符；③ 最终必须消掉全部非终结符并恰好得到目标串。若目标串的开头、结尾已经违反产生式结构，可先快速排除。</p><p><strong>闭包与正则闭包（公式三件套）</strong>：</p><ul><li><strong>通用形式</strong>：正则闭包 A⁺ = A¹ ∪ A² ∪ …（<strong>1 个或多个</strong> A 连接）；闭包 A* = A⁰ ∪ A⁺（在正则闭包基础上<strong>加上 A⁰ = {ε}</strong>，ε 是空串）。</li><li><strong>代入算例</strong>：A = {ab} 时，A⁺ = {ab, abab, ababab, …}；A* = {ε, ab, abab, …}——只多一个空串 ε。</li><li><strong>手算口诀</strong>：<strong>&quot;加 1 乘 0&quot;</strong>——<code>+</code> 表示 1～n 个（不含空串），<code>*</code> 表示 0～n 个（含空串）。</li></ul><h3 id="_5-3-语法推导树" tabindex="-1">5.3 语法推导树 <a class="header-anchor" href="#_5-3-语法推导树" aria-label="Permalink to &quot;5.3 语法推导树&quot;">​</a></h3><p>从起始符 S 出发按产生式展开：根是 S，内部结点是非终结符，叶子从左到右拼起来就是句子。上例 <code>aabb</code> 的树可写成：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>          S</span></span>
<span class="line"><span>        /   \\</span></span>
<span class="line"><span>       A     B</span></span>
<span class="line"><span>      / \\   / \\</span></span>
<span class="line"><span>     a   A b   B</span></span>
<span class="line"><span>         |     |</span></span>
<span class="line"><span>         a     b</span></span></code></pre></div><p>叶子从左到右为 <code>a a b b</code>，与目标串一致；树的左、右子树也分别满足 A、B 的产生式。<strong>教学图反向检查</strong>：每个内部结点展开出的孩子必须恰好等于某条产生式右部，不能为了凑目标串随意添叶子。</p><p><strong>重要结论</strong>：常见的程序设计语言（C、Java 等）的语法规则通常是<strong>上下文无关文法</strong>——选择题直接考这个结论。</p><p><strong>应试动作</strong>：① 四元组各成分一句话定义；② 能区分“仍含非终结符的句型”与“只含终结符的句子”；③ 题目指定最左/最右推导时，每步只换对应一侧的非终结符；④ 背“程序语言通常用上下文无关文法”。闭包公式放在本节是为了服务正规式，口诀仍是“加 1 乘 0”。</p>`,25)])])}const h=t(o,[["render",p]]);export{g as __pageData,h as default};
